import{z as l,x as d,o as E,c as D,q as i,j as s,D as e,d as r,s as n,S as A,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"STRIDE","description":"","frontmatter":{"title":"STRIDE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stride.md","filePath":"cs/stride.md","lastUpdated":1791413859000}'),B={name:"cs/stride.md"};function p(c,a,m,S,T,h){const o=d("Mermaid");return E(),D("div",null,[a[2]||(a[2]=i('<h1 id="stride" tabindex="-1">STRIDE <a class="header-anchor" href="#stride" aria-label="Permalink to &quot;STRIDE&quot;">​</a></h1><div class="epigraph"><p>伪造、篡改、否认、信息泄露、拒绝服务、越权：六类检查清单，把威胁模型从一张空图变成可枚举的问句。</p><footer>—— 据 Howard and Lipner；Shostack, Threat Modeling；Anderson 对把威胁写下来的强调</footer></div><p><a href="/cs/threat-model">上一课</a>要求先写敌手、资产与信任边界。本课不重画 Kerckhoffs。缺口是检查时容易漏轴：<a href="/cs/cia-triad">CIA</a> 是三根，工程审查常用 STRIDE 六类把「谁能干什么」问全。它是清单，不是攻击教程。后课 Dolev–Yao 再把网络敌手收成代数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>威胁模型课留下「映射到机制」。评审一张数据流图时，每个过程、每个数据流、每个存储都要问：身份能否被假冒，数据能否被改，事件能否被抵赖，秘密能否流出，服务能否被停，授权能否被绕过。缺口是<strong>把这些问题命名成 STRIDE</strong>，避免只盯着加密。</p><p><span class="marginnote">STRIDE 来自微软一线教材，不是密码学定理。否认（R）常要日志与签名，和 CIA 的 I 相关但不相同。</span></p><p><span class="marginnote">六类各取英文首字母：Spoofing 伪造（冒充别人）、Tampering 篡改、Repudiation 否认（做了不认）、Information Disclosure 泄露、Denial of Service 拒绝服务、Elevation of Privilege 越权——记首字母不如记这六句问话。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对图上每个元素过六问，记下「不防谁」。然后才选后课机制：对称加密对泄露，MAC 对篡改，认证对伪造，隔离对越权，容量设计对 DoS。本课不把某一次审查表格当标准正文。</p><p><span class="marginnote">实际怎么用：把数据流图上的每个元素过一遍六问——「这个 API 能否认请求来自自己吗」问的是否认，「这个队列被打满会怎样」问的是拒绝服务；答案若是「不防」，就记一条待办。清单的价值在逼出「不防谁」。</span></p>',10)),(E(),s(A,null,{default:e(()=>[n(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DFD%5B%22%E6%95%B0%E6%8D%AE%E6%B5%81%E5%9B%BE%22%5D%20--%3E%20S%5B%22%E4%BC%AA%E9%80%A0%22%5D%0A%20%20DFD%20--%3E%20T%5B%22%E7%AF%A1%E6%94%B9%22%5D%0A%20%20DFD%20--%3E%20R%5B%22%E5%90%A6%E8%AE%A4%22%5D%0A%20%20DFD%20--%3E%20I%5B%22%E6%B3%84%E9%9C%B2%22%5D%0A%20%20DFD%20--%3E%20D%5B%22%E6%8B%92%E7%BB%9D%E6%9C%8D%E5%8A%A1%22%5D%0A%20%20DFD%20--%3E%20E%5B%22%E8%B6%8A%E6%9D%83%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"清单迫使每个信任边界都有对应控制，而不是全局一句「有 TLS」。它与后课访问控制、握手、沙箱是多对多：一种机制可挡多类，一类威胁要多层。本栏不提供利用步骤，只要求设计时能指出控制落点。",-1)),(E(),s(A,null,{default:e(()=>[n(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20TLS%5B%22%E5%8F%AA%E9%83%A8%E7%BD%B2%E4%B8%80%E5%B1%82%20TLS%22%5D%20--%3E%20COV%5B%22%E6%8C%A1%E4%BD%8F%EF%BC%9A%E4%BC%A0%E8%BE%93%E6%AE%B5%E6%B3%84%E9%9C%B2%E4%B8%8E%E9%83%A8%E5%88%86%E4%BC%AA%E9%80%A0%22%5D%0A%20%20TLS%20--%3E%20NO%5B%22%E6%8C%A1%E4%B8%8D%E4%BD%8F%EF%BC%9A%E5%90%A6%E8%AE%A4%E3%80%81DoS%E3%80%81%E8%B6%8A%E6%9D%83%22%5D%0A%20%20NO%20--%3E%20LOG%5B%22%E8%A1%A5%E6%97%A5%E5%BF%97%E4%B8%8E%E7%AD%BE%E5%90%8D%EF%BC%9A%E5%AF%B9%E5%90%A6%E8%AE%A4%22%5D%0A%20%20NO%20--%3E%20CAP%5B%22%E8%A1%A5%E5%AE%B9%E9%87%8F%E4%B8%8E%E9%99%90%E6%B5%81%EF%BC%9A%E5%AF%B9%20DoS%22%5D%0A%20%20NO%20--%3E%20AUTHZ%5B%22%E8%A1%A5%E5%BA%94%E7%94%A8%E5%B1%82%E6%8E%88%E6%9D%83%E6%A3%80%E6%9F%A5%EF%BC%9A%E5%AF%B9%E8%B6%8A%E6%9D%83%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">常见误区：初学者以为装了 TLS 就「安全了」。实际上 TLS 只覆盖传输段的泄露与部分伪造——否认靠日志与签名、DoS 靠容量与限流、越权靠应用层授权，各自都是独立的控制落点。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 STRIDE 当成完备分类，不引入攻击树的全部记号。能改写、能注入的网络敌手下一课用 Dolev–Yao 形式化。</p><p>后课默认：审查用六类问句。协议层敌手能力下一课钉死。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>STRIDE 是威胁模型上的检查清单，不是新的 CIA。</li><li>每问应对到后课某一机制。</li><li>网络代数敌手下一课 Dolev–Yao。</li><li>出处：Howard and Lipner；Shostack；Anderson, <em>Security Engineering</em>。</li></ul>',6))])}const _=l(B,[["render",p]]);export{u as __pageData,_ as default};
